public class SP {
    public Schema.SObjectType typ(String name) { return Schema.getGlobalDescribe().get(name); }
    public String field(String obj, String name) {
        Schema.SObjectField f=typ(obj).getDescribe().fields.getMap().get(name);
        if(f==null) return 'absent';
        Schema.DescribeFieldResult d=f.getDescribe();
        return d.getName()+'|'+d.getType()+'|length='+d.getLength()
          +'|precision='+d.getPrecision()+'|scale='+d.getScale()
          +'|null='+d.isNillable()+'|defaulted='+d.isDefaultedOnCreate();
    }
    public String compound(String obj, String name) {
        Schema.SObjectField f=typ(obj).getDescribe().fields.getMap().get(name);
        if(f==null) return 'absent';
        Schema.DescribeFieldResult d=f.getDescribe();
        return d.getName()+'|'+d.getType()+'|parent='+d.getCompoundFieldName()
          +'|create='+d.isCreateable()+'|update='+d.isUpdateable();
    }
}
